#!/bin/sh
# Generated by Bernard the taktician. Do not edit: change .factory/ and run `bernard sync`.
# Claude Code runs it after each edit (.claude/settings.json): an edit of .factory/ syncs the files it renders.
[ -n "${CLAUDE_PROJECT_DIR:-}" ] || exit 0
bernard="$CLAUDE_PROJECT_DIR/.factory/node_modules/.bin/bernard"
[ -f "$bernard" ] && [ -x "$bernard" ] || exit 0
command -v node >/dev/null 2>&1 || exit 0
payload=$(cat)
case $payload in
  *.factory*) ;;
  *) exit 0 ;;
esac
printf '%s\n' "$payload" | "$bernard" sync --hook --cwd "$CLAUDE_PROJECT_DIR"
